import sys
sys.setrecursionlimit(10 ** 6)
input = sys.stdin.readline
for t in range(int(input())):
	n = int(input())
	s = input()
	graph = [[] for _ in range(n + 1)]
	for _ in range(n - 1):
		(u, v) = map(int, input().split())
		if s[u - 1] == 'R' and s[v - 1] == 'G' or (s[u - 1] == 'G' and s[v - 1] == 'R'):
			continue
		graph[u].append(v)
		graph[v].append(u)
	visit = set()

	def dfs(u, count):
		visit.add(u)
		if s[u - 1] == 'B':
			count[0] += 1
		if count[0] > 1:
			return False
		for v in graph[u]:
			if v not in visit:
				if not dfs(v, count):
					return False
		return True
	flag = False
	for i in range(1, n + 1):
		if i not in visit:
			if not dfs(i, [0]):
				flag = True
				break
	if flag:
		print('No')
	else:
		print('Yes')
